const state = String(($json.body && $json.body.state) ?? $json.state ?? '').toLowerCase();
let pick;
if (state.includes('production server is down')) pick = CANNED['ticket-1-infra'];
else if (state.includes('charged twice')) pick = CANNED['ticket-2-billing'];
else if (state.includes('volume discounts')) pick = CANNED['ticket-3-sales'];
else pick = CANNED['ticket-4-hmm'];

return [{ json: { canned: pick } }];
